namespace MyApp.Application.Features.DadosBase.Navios;

/// <summary>Obtém o detalhe de um navio.</summary>
/// <param name="repositorio">Repositório de navios.</param>
internal sealed class GetNavioUseCase(INavioRepositorio repositorio)
{
    private readonly INavioRepositorio _repository = repositorio;

    /// <summary>Obtém o navio da consulta.</summary>
    /// <param name="query">Consulta com o id do navio.</param>
    /// <param name="cancellationToken">Token de cancelamento.</param>
    /// <returns>O navio encontrado, ou o erro da consulta.</returns>
    public async Task<Result<NavioReadModel>> HandleAsync(
        ObterNavioQuery query,
        CancellationToken cancellationToken = default)
    {
        if (query.Invalid)
            return new Result<NavioReadModel>(query.Notifications);

        var navio = await _repository.GetByIdAsync(query.Id, cancellationToken);

        if (navio is null)
            return new Result<NavioReadModel>(nameof(query.Id), "Navio não encontrado.");

        return new Result<NavioReadModel>(navio);
    }
}
